import { zValidator } from '@hono/zod-validator';
import { Hono } from 'hono';
import { authMiddleware, requireVendor, } from '../../middleware/auth.middleware.js';
import * as vendorsController from './vendors.controller.js';
import { createServiceAreaSchema, createServiceSchema, createVendorSchema, listPublicVendorsQuerySchema, reorderPhotosSchema, resourceIdParamSchema, setWorkingHoursSchema, slotsQuerySchema, toggleServiceActiveSchema, updateJobTypesSchema, updateServiceSchema, updateSlotIntervalSchema, updateVendorSchema, vendorIdParamSchema, } from './vendors.validation.js';
export const vendorsRoutes = new Hono();
const ownerMiddleware = [authMiddleware, requireVendor];
vendorsRoutes.get('/', zValidator('query', listPublicVendorsQuerySchema), (c) => vendorsController.listPublicVendors(c, c.req.valid('query')));
vendorsRoutes.post('/', authMiddleware, zValidator('json', createVendorSchema), (c) => vendorsController.createVendor(c, c.req.valid('json')));
vendorsRoutes.get('/me', ...ownerMiddleware, vendorsController.getMyVendor);
vendorsRoutes.patch('/me', ...ownerMiddleware, zValidator('json', updateVendorSchema), (c) => vendorsController.updateVendor(c, c.req.valid('json')));
vendorsRoutes.patch('/me/job-types', ...ownerMiddleware, zValidator('json', updateJobTypesSchema), (c) => vendorsController.updateJobTypes(c, c.req.valid('json')));
vendorsRoutes.patch('/me/slot-interval', ...ownerMiddleware, zValidator('json', updateSlotIntervalSchema), (c) => vendorsController.updateSlotInterval(c, c.req.valid('json')));
vendorsRoutes.get('/me/working-hours', ...ownerMiddleware, vendorsController.getWorkingHours);
vendorsRoutes.put('/me/working-hours', ...ownerMiddleware, zValidator('json', setWorkingHoursSchema), (c) => vendorsController.setWorkingHours(c, c.req.valid('json')));
vendorsRoutes.get('/me/service-areas', ...ownerMiddleware, vendorsController.listServiceAreas);
vendorsRoutes.post('/me/service-areas', ...ownerMiddleware, zValidator('json', createServiceAreaSchema), (c) => vendorsController.createServiceArea(c, c.req.valid('json')));
vendorsRoutes.delete('/me/service-areas/:id', ...ownerMiddleware, zValidator('param', resourceIdParamSchema), (c) => vendorsController.deleteServiceArea(c, c.req.valid('param').id));
vendorsRoutes.get('/me/photos', ...ownerMiddleware, vendorsController.listPhotos);
vendorsRoutes.patch('/me/photos/order', ...ownerMiddleware, zValidator('json', reorderPhotosSchema), (c) => vendorsController.reorderPhotos(c, c.req.valid('json')));
vendorsRoutes.delete('/me/photos/:id', ...ownerMiddleware, zValidator('param', resourceIdParamSchema), (c) => vendorsController.deletePhoto(c, c.req.valid('param').id));
vendorsRoutes.get('/me/services', ...ownerMiddleware, vendorsController.listMyServices);
vendorsRoutes.post('/me/services', ...ownerMiddleware, zValidator('json', createServiceSchema), (c) => vendorsController.createService(c, c.req.valid('json')));
vendorsRoutes.patch('/me/services/:id/active', ...ownerMiddleware, zValidator('param', resourceIdParamSchema), zValidator('json', toggleServiceActiveSchema), (c) => vendorsController.toggleServiceActive(c, c.req.valid('param').id, c.req.valid('json')));
vendorsRoutes.patch('/me/services/:id', ...ownerMiddleware, zValidator('param', resourceIdParamSchema), zValidator('json', updateServiceSchema), (c) => vendorsController.updateService(c, c.req.valid('param').id, c.req.valid('json')));
vendorsRoutes.delete('/me/services/:id', ...ownerMiddleware, zValidator('param', resourceIdParamSchema), (c) => vendorsController.deleteService(c, c.req.valid('param').id));
vendorsRoutes.get('/:id/slots', zValidator('query', slotsQuerySchema), zValidator('param', vendorIdParamSchema), (c) => vendorsController.getAvailableSlots(c, c.req.valid('param').id, c.req.valid('query')));
vendorsRoutes.get('/:id/services', zValidator('param', vendorIdParamSchema), (c) => vendorsController.listPublicServices(c, c.req.valid('param').id));
vendorsRoutes.get('/:id', zValidator('param', vendorIdParamSchema), (c) => vendorsController.getPublicVendor(c, c.req.valid('param').id));
